PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'siswa', foto TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ekskul (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, deskripsi TEXT, pembina_id INTEGER REFERENCES users(id) ON DELETE SET NULL, kuota INTEGER NOT NULL DEFAULT 30, requires_approval INTEGER NOT NULL DEFAULT 0, hari TEXT, jam_mulai TEXT, jam_selesai TEXT, lokasi TEXT, cover_path TEXT, status TEXT NOT NULL DEFAULT 'pending', registration_start DATETIME, registration_end DATETIME, is_dummy INTEGER NOT NULL DEFAULT 0, deleted_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ekskul_id INTEGER NOT NULL REFERENCES ekskul(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'menunggu', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME, UNIQUE(user_id, ekskul_id));
CREATE TABLE IF NOT EXISTS schedules (id INTEGER PRIMARY KEY AUTOINCREMENT, ekskul_id INTEGER NOT NULL REFERENCES ekskul(id) ON DELETE CASCADE, tanggal TEXT NOT NULL, jam_mulai TEXT NOT NULL, jam_selesai TEXT NOT NULL, lokasi TEXT, tipe TEXT NOT NULL DEFAULT 'rutin', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY AUTOINCREMENT, schedule_id INTEGER NOT NULL REFERENCES schedules(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'hadir', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(schedule_id, user_id));
CREATE TABLE IF NOT EXISTS attendance_tokens (token TEXT PRIMARY KEY, ekskul_id INTEGER NOT NULL REFERENCES ekskul(id) ON DELETE CASCADE, schedule_id INTEGER NOT NULL REFERENCES schedules(id) ON DELETE CASCADE, expiry DATETIME NOT NULL, used INTEGER NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, nama TEXT NOT NULL, deskripsi TEXT, tanggal TEXT NOT NULL, waktu TEXT NOT NULL, lokasi TEXT, cover_path TEXT, kuota INTEGER NOT NULL DEFAULT 50, rundown TEXT, ekskul_id INTEGER NULL REFERENCES ekskul(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'pending', registration_start DATETIME, registration_end DATETIME, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_ekskul (event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, ekskul_id INTEGER NOT NULL REFERENCES ekskul(id) ON DELETE CASCADE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (event_id, ekskul_id));
CREATE TABLE IF NOT EXISTS event_participants (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'diterima', hadir INTEGER NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(event_id, user_id));
CREATE TABLE IF NOT EXISTS event_attendance_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, nama TEXT NOT NULL DEFAULT 'Sesi 1', token TEXT NOT NULL UNIQUE, durasi_jam INTEGER NOT NULL DEFAULT 10, starts_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, status TEXT NOT NULL DEFAULT 'aktif', created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_attendance (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL REFERENCES event_attendance_sessions(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, scanned_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id, user_id));
CREATE TABLE IF NOT EXISTS announcements (id INTEGER PRIMARY KEY AUTOINCREMENT, judul TEXT NOT NULL, isi TEXT NOT NULL, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS remember_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, selector TEXT NOT NULL UNIQUE, validator_hash TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at DATETIME NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, run_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, payload TEXT NOT NULL DEFAULT '{}', result TEXT NULL, error TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_jobs_claim ON jobs(status, run_at);
